#define JINGLE_N 956

u16 capcom_logo_cram[16];

/* YM2612 register write with a bounded busy wait (the 68k owns the Z80 bus
 * here): SGDK's register write spins on the busy flag without a limit, so
 * a chip that never reports ready would hang the boot on a black screen.
 * ~1000 polls is far beyond any real busy period (a few dozen cycles). */
static void ym_write(u16 part, u8 reg, u8 val)
{
    vs8 *pb = (s8 *) YM2612_BASEPORT;
    u16 port = (u16)((part << 1) & 2), n = 1000;
    while (*pb < 0 && --n) { }
    pb[port + 0] = (s8)reg;
    __asm__ volatile ("nop");
    pb[port + 1] = (s8)val;
    __asm__ volatile ("nop\n\tnop\n\tnop\n\tnop\n\tnop");
}
static u16 seq_t;
static u16 ev_i;

void capcom_logo_draw(u16 vramBase, u16 x, u16 y)
{
    VDP_loadTileData(capcom_logo_tiles, vramBase, CAPCOM_LOGO_TILE_COUNT, DMA);
    for (u16 i = 0; i < 36; i++)
        VDP_setTileMapXY(BG_A, (u16)(vramBase + i), x + (i % 12), y + (i / 12));
}

/* per-channel: max(0, target - 2k) -- the engine's fade (verified) */
static void fade_to(u16 k)
{
    for (u16 i = 0; i < 16; i++) {
        u16 c = base_pal[i];
        u16 b = (c >> 8) & 0xF, g = (c >> 4) & 0xF, r = c & 0xF;
        u16 s = k * 2;
        b = (b > s) ? (b - s) : 0;
        g = (g > s) ? (g - s) : 0;
        r = (r > s) ? (r - s) : 0;
        capcom_logo_cram[i] = (u16)((b << 8) | (g << 4) | r);
    }
}

void capcom_intro_reset(void)
{
    for (u16 i = 0; i < 16; i++) capcom_logo_cram[i] = 0x0000;
    seq_t = 0; ev_i = 0;
    /* restore the original driver's YM state (instrument patches etc.) */
    for (u16 i = 0; i < SETUP_N; i++)
        ym_write(jingle_setup[i*3], jingle_setup[i*3 + 1],
                        jingle_setup[i*3 + 2]);
}

u16 capcom_intro_step(void)
{
    seq_t++;
    /* jingle: write this frame's FM events */
    while (ev_i < JINGLE_N && jingle_ev[ev_i * 4] == seq_t - 1) {
        ym_write(jingle_ev[ev_i*4 + 1], jingle_ev[ev_i*4 + 2],
                        jingle_ev[ev_i*4 + 3]);
        ev_i++;
    }
    /* fade-in: t=34..58, k=6..0 every 4 frames */
    if (seq_t >= 34 && seq_t <= 58 && ((seq_t - 34) & 3) == 0)
        fade_to(6 - ((seq_t - 34) >> 2));
    /* glint states */
    for (u16 i = 0; i < 6; i++)
        if (seq_t == glint_t[i]) {
            const u16 *g = &glint_pal[i * 16];
            for (u16 j = 0; j < 16; j++) capcom_logo_cram[j] = g[j];
        }
    /* fade-out: t=333..357, k=1..7 every 4 frames */
    if (seq_t >= 333 && seq_t <= 357 && ((seq_t - 333) & 3) == 0)
        fade_to(1 + ((seq_t - 333) >> 2));
    return (seq_t < CAPCOM_INTRO_FRAMES) ? 1 : 0;
}
